(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.3)*18 + Math.sin(x*0.02+t*0.32)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.4)*8 + Math.cos((y+w1y)*0.03+t*0.35)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.38)*8 + Math.sin((x+w1x)*0.028-t*0.42)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8, 1.3]
  ];
  let aS=0, iS=0, dS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    dS += Math.sin(d*f*0.4+t*sp*0.3+3.0)*w*0.5;
  }
  const tw = 5.4;
  const act=aS/tw, inh=iS/tw, dif=dS/tw;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    + Math.sin((sx+sy)*0.11+t*2.2)*0.2 + Math.sin((sx-sy)*0.09-t*1.8)*0.2
    + Math.sin(sx*0.06+sy*0.02-t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1)
    + Math.sin(dist*0.06-ang*2-t*2.0))*0.3;
  const micro = (Math.sin(sx*0.22+t*3)*Math.sin(sy*0.22-t*2.5)
    + Math.sin((sx-sy)*0.18+t*2)*Math.cos((sx+sy)*0.15-t*1.8))*0.15;
  const feed = act - inh*0.65 + bg*0.25 + spiral*0.4 + dif*0.2 + micro;
  const reaction = Math.tanh(feed*2.0);
  const laplacian = Math.sin(sx*0.12)*Math.sin(sy*0.12)*0.4
    + Math.sin((sx+sy)*0.08+t*0.8)*0.3
    + Math.sin((sx*0.5|0)*0.8+(sy*0.5|0)*0.6)*0.1;
  const cell = Math.tanh((reaction + laplacian)*1.3)*0.3;
  const pulse = Math.sin(t*0.8)*0.1+Math.sin(t*1.3+1)*0.05;
  const blend = reaction*0.65 + cell*0.25 + pulse*0.1;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const hueShift = Math.sin(t*0.15)*0.08 + Math.sin(t*0.23+2)*0.05;
  const pal = [
    [5,12,52],[8,35,82],[12,65,105],[18,105,128],
    [30,148,138],[85,172,115],[175,185,80],
    [215,175,60],[225,135,65],[195,85,72],
    [155,48,82],[95,25,68],[40,15,55],[5,12,52]
  ];
  const idx = (v+hueShift)*(pal.length-1);
  const ci = ((idx%pal.length)+pal.length)%pal.length;
  const i = Math.min(ci|0, pal.length-2), f = ci-i;
  const intensity = Math.abs(reaction);
  const lum = 0.75 + intensity*0.25 + Math.sin(reaction*Math.PI)*0.1;
  const glow = intensity>0.6 ? 1.0+(intensity-0.6)*0.6 : 1.0;
  const edge = Math.abs(reaction)>0.72 ? 1.2 : (Math.abs(reaction)<0.15 ? 0.85 : 1.0);
  const m = lum*glow*edge;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
